#define F_CPU 1200000UL
#include <avr/io.h>
#include <util/delay.h>

// --- Настройка пинов ---
#define CLK_PIN PB0  // Pin 5 (TM1637 CLK + Кнопка на GND)
#define DIO_PIN PB1  // Pin 6 (TM1637 DIO)
#define RTC_CLK PB2  // Pin 7 (DS1302 CLK)
#define RTC_DAT PB3  // Pin 2 (DS1302 DAT)
#define RTC_RST PB4  // Pin 3 (DS1302 RST / CE)

const uint8_t digitMap[] = {
    0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F // 0..9
};

// --- Быстрые функции разложения на десятки и единицы (без деления) ---
static inline uint8_t get_tens(uint8_t val) {
    uint8_t t = 0;
    while (val >= 10) { val -= 10; t++; }
    return t;
}

static inline uint8_t get_units(uint8_t val) {
    while (val >= 10) { val -= 10; }
    return val;
}

// --- ДРАЙВЕР TM1637 ---
void tm_start(void) {
    DDRB |= (1 << DIO_PIN) | (1 << CLK_PIN);
    PORTB |= (1 << DIO_PIN) | (1 << CLK_PIN); _delay_us(5);
    PORTB &= ~(1 << DIO_PIN); _delay_us(5);
    PORTB &= ~(1 << CLK_PIN);
}

void tm_stop(void) {
    PORTB &= ~(1 << DIO_PIN); PORTB &= ~(1 << CLK_PIN); _delay_us(5);
    PORTB |= (1 << CLK_PIN); PORTB |= (1 << DIO_PIN); _delay_us(5);
}

void tm_write_byte(uint8_t b) {
    for (uint8_t i = 0; i < 8; i++) {
        PORTB &= ~(1 << CLK_PIN);
        if (b & 0x01) PORTB |= (1 << DIO_PIN); 
        else PORTB &= ~(1 << DIO_PIN);
        _delay_us(5);
        PORTB |= (1 << CLK_PIN);
        _delay_us(5);
        b >>= 1;
    }
    PORTB &= ~(1 << CLK_PIN);
    DDRB &= ~(1 << DIO_PIN); // ACK
    _delay_us(5);
    PORTB |= (1 << CLK_PIN);
    _delay_us(5);
    DDRB |= (1 << DIO_PIN);
}

void display_time(uint8_t hour, uint8_t min, uint8_t show_dots, uint8_t blink_mask) {
    tm_start(); tm_write_byte(0x40); tm_stop();
    tm_start();
    tm_write_byte(0xC0);

    // Часы
    if (blink_mask & 0x01) {
        tm_write_byte(digitMap[get_tens(hour)]);
        tm_write_byte(digitMap[get_units(hour)] | (show_dots ? 0x80 : 0x00));
    } else {
        tm_write_byte(0x00); tm_write_byte(0x00);
    }

    // Минуты
    if (blink_mask & 0x02) {
        tm_write_byte(digitMap[get_tens(min)]);
        tm_write_byte(digitMap[get_units(min)]);
    } else {
        tm_write_byte(0x00); tm_write_byte(0x00);
    }
    tm_stop();

    tm_start(); tm_write_byte(0x8A); tm_stop(); // Яркость
}

// --- ДРАЙВЕР DS1302 ---
uint8_t dec2bcd(uint8_t val) { 
    return (get_tens(val) << 4) | get_units(val); 
}

uint8_t bcd2dec(uint8_t val) { 
    uint8_t tens = val >> 4;
    uint8_t res = val & 0x0F;
    while (tens--) res += 10;
    return res;
}

void ds1302_write_byte(uint8_t data) {
    for (uint8_t i = 0; i < 8; i++) {
        if (data & 0x01) PORTB |= (1 << RTC_DAT);
        else PORTB &= ~(1 << RTC_DAT);
        PORTB |= (1 << RTC_CLK); _delay_us(5);
        PORTB &= ~(1 << RTC_CLK); _delay_us(5);
        data >>= 1;
    }
}

uint8_t ds1302_read_byte(void) {
    uint8_t data = 0;
    DDRB &= ~(1 << RTC_DAT);
    for (uint8_t i = 0; i < 8; i++) {
        if (PINB & (1 << RTC_DAT)) data |= (1 << i);
        PORTB |= (1 << RTC_CLK); _delay_us(5);
        PORTB &= ~(1 << RTC_CLK); _delay_us(5);
    }
    DDRB |= (1 << RTC_DAT);
    return data;
}

void ds1302_write_reg(uint8_t reg, uint8_t val) {
    PORTB |= (1 << RTC_RST); _delay_us(5);
    ds1302_write_byte(reg);
    ds1302_write_byte(val);
    PORTB &= ~(1 << RTC_RST); _delay_us(5);
}

uint8_t ds1302_read_reg(uint8_t reg) {
    PORTB |= (1 << RTC_RST); _delay_us(5);
    ds1302_write_byte(reg | 0x01);
    uint8_t val = ds1302_read_byte();
    PORTB &= ~(1 << RTC_RST); _delay_us(5);
    return val;
}

void ds1302_init(void) {
    DDRB |= (1 << RTC_CLK) | (1 << RTC_DAT) | (1 << RTC_RST);
    PORTB &= ~((1 << RTC_CLK) | (1 << RTC_RST));
    
    _delay_ms(10);
    ds1302_write_reg(0x8E, 0x00); // Снять WP
    
    if (ds1302_read_reg(0x80) & 0x80) {
        ds1302_write_reg(0x80, 0x00); // Запуск генератора
    }
}

void save_time_to_rtc(uint8_t hour, uint8_t min) {
    ds1302_write_reg(0x8E, 0x00);
    ds1302_write_reg(0x80, 0x00);
    ds1302_write_reg(0x82, dec2bcd(min));
    ds1302_write_reg(0x84, dec2bcd(hour));
}

// --- ОПРОС КНОПКИ (PB0) ---
uint8_t check_button(void) {
    DDRB &= ~(1 << CLK_PIN);
    PORTB |= (1 << CLK_PIN);
    _delay_us(20);

    if (!(PINB & (1 << CLK_PIN))) {
        _delay_ms(30);
        if (!(PINB & (1 << CLK_PIN))) {
            uint8_t timer = 0;
            while (!(PINB & (1 << CLK_PIN))) {
                _delay_ms(15);
                if (++timer > 80) { // Зажатие > 1.2 сек
                    while (!(PINB & (1 << CLK_PIN)));
                    return 2;
                }
            }
            return 1;
        }
    }
    return 0;
}

int main(void) {
    DDRB |= (1 << CLK_PIN) | (1 << DIO_PIN);
    _delay_ms(100);

    ds1302_init();

    uint8_t hour = 12, min = 0;
    uint8_t mode = 0;
    uint8_t blink = 0;
    uint8_t dots = 0;

    while (1) {
        uint8_t btn = check_button();

        if (mode == 0) {
            if (btn == 2) {
                mode = 1;
            } else {
                uint8_t raw_m = ds1302_read_reg(0x82);
                uint8_t raw_h = ds1302_read_reg(0x84);
                
                if (raw_m != 0xFF && raw_h != 0xFF) {
                    min = bcd2dec(raw_m);
                    hour = bcd2dec(raw_h);
                }
                
                dots = !dots;
                display_time(hour, min, dots, 0x03);
                _delay_ms(350);
            }
        } 
        else if (mode == 1) {
            if (btn == 1) {
                if (++hour >= 24) hour = 0;
            } else if (btn == 2) mode = 2;
            
            blink = !blink;
            display_time(hour, min, 1, blink ? 0x03 : 0x02);
            _delay_ms(150);
        } 
        else if (mode == 2) {
            if (btn == 1) {
                if (++min >= 60) min = 0;
            } else if (btn == 2) {
                save_time_to_rtc(hour, min);
                mode = 0;
            }
            blink = !blink;
            display_time(hour, min, 1, blink ? 0x03 : 0x01);
            _delay_ms(150);
        }
    }
}
